function total(arr: number[]): number {
  let sum = 0
  for (const x of arr) { // O(n): runs once per item
    sum += x
  }
  return sum
}

function binarySearch(sorted: number[], target: number): number {
  let lo = 0
  let hi = sorted.length - 1
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2)
    if (sorted[mid] === target) return mid
    if (sorted[mid] < target) lo = mid + 1  // throw away the left half
    else hi = mid - 1                       // throw away the right half
  }
  return -1
}

